128	     only <Content> scrolls on screen; printing needs the opposite — the page
129	     must lay out to its natural (paginated) height, and the screen padding
130	     would otherwise just be blank margin around a hidden `.no-print` tree. */
131	  .ant-layout,
132	  .ant-layout-content {
133	    height: auto !important;
134	    overflow: visible !important;
135	    padding: 0 !important;
136	    margin: 0 !important;
137	  }
