// Sets data-theme before first paint so a dark-preferring visitor never sees a
// flash of the light theme. A same-origin file, not an inline script — the CSP's
// script-src has no 'unsafe-inline'. Mirrors ThemeModeProvider's own resolution
// exactly — keep the two in sync if either changes.
(function () {
  try {
    var stored = localStorage.getItem('dq-theme-mode');
    var mode = stored === 'light' || stored === 'dark' || stored === 'system' ? stored : 'system';
    var resolved =
      mode === 'system'
        ? window.matchMedia('(prefers-color-scheme: dark)').matches
          ? 'dark'
          : 'light'
        : mode;
    document.documentElement.setAttribute('data-theme', resolved);
  } catch (e) {
    // localStorage/matchMedia unavailable — ThemeModeProvider's own effect will
    // set it once React mounts.
  }
})();

