async (page) => {
  const context = page.context();
  const newPage = await context.newPage();
  // Block the React module bundle entirely — if data-theme is still set correctly,
  // theme-init.js (not React's ThemeModeProvider effect) is what set it.
  await newPage.route('**/main.tsx', route => route.abort());
  await newPage.goto('http://localhost:5186/');
  const theme = await newPage.evaluate(() => document.documentElement.getAttribute('data-theme'));
  await newPage.close();
  return { theme };
}

