11	function readStoredMode(): ThemeModePreference {
12	  try {
13	    const stored = localStorage.getItem(STORAGE_KEY);
14	    if (stored === 'light' || stored === 'dark' || stored === 'system') return stored;
15	  } catch {
16	    // localStorage unavailable (private browsing, disabled) — fall back below.
17	  }
18	  return 'system';
19	}
