21	function systemPrefersDark(): boolean {
22	  return window.matchMedia('(prefers-color-scheme: dark)').matches;
23	}
24	
25	export function ThemeModeProvider({ children }: { children: ReactNode }) {
26	  const [mode, setModeState] = useState<ThemeModePreference>(readStoredMode);
27	  const [systemDark, setSystemDark] = useState(systemPrefersDark);
28	
29	  useEffect(() => {
30	    const mql = window.matchMedia('(prefers-color-scheme: dark)');
31	    const onChange = (e: MediaQueryListEvent) => setSystemDark(e.matches);
32	    mql.addEventListener('change', onChange);
33	    return () => mql.removeEventListener('change', onChange);
34	  }, []);
35	
36	  const resolvedMode: ResolvedThemeMode =
37	    mode === 'system' ? (systemDark ? 'dark' : 'light') : mode;
38	
39	  useEffect(() => {
40	    document.documentElement.setAttribute('data-theme', resolvedMode);
41	  }, [resolvedMode]);
42	
43	  function setMode(next: ThemeModePreference) {
44	    setModeState(next);
45	    try {
46	      localStorage.setItem(STORAGE_KEY, next);
47	    } catch {
48	      // Best-effort persistence — the in-memory mode still applies this session.
49	    }
50	  }
51	
52	  const value = useMemo(() => ({ mode, resolvedMode, setMode }), [mode, resolvedMode]);
53	
54	  return <ThemeModeContext.Provider value={value}>{children}</ThemeModeContext.Provider>;
55	}
